from pathlib import Path

p = Path('sethiportfolio-admin.html')
s = p.read_text(encoding='utf-8')

marker = '''            <div class="grid xl:grid-cols-[1fr_1fr] gap-6 items-start">\n'''
card = '''            <section class="card mb-6 overflow-hidden">\n                <div class="p-5 md:p-6 border-b border-gray-100 flex flex-col lg:flex-row lg:items-start justify-between gap-4">\n                    <div>\n                        <p class="text-[10px] font-black uppercase tracking-[0.14em] text-blue-700">Active allocation</p>\n                        <h2 class="text-xl font-black mt-1">Fund a New Investment Idea</h2>\n                        <p class="text-xs text-gray-500 mt-1 max-w-3xl">Record the funding sale and new purchase as one portfolio decision. Both legs are validated together before either transaction is written.</p>\n                    </div>\n                    <span class="text-[9px] font-black uppercase tracking-wider rounded-full bg-blue-50 text-blue-700 border border-blue-100 px-2 py-1 self-start">Paired ledger write</span>\n                </div>\n                <form id="allocation-form" class="p-5 md:p-6 space-y-5">\n                    <div class="grid lg:grid-cols-[.7fr_1.15fr_1.15fr] gap-5">\n                        <div>\n                            <label class="label" for="allocation-date">Trade date</label>\n                            <input id="allocation-date" type="date" class="field" required>\n                            <p class="text-[11px] text-gray-400 leading-relaxed mt-2">Both legs use the same effective trade date.</p>\n                        </div>\n                        <div class="rounded-xl border border-gray-200 bg-gray-50 p-4 space-y-3">\n                            <div class="flex items-center justify-between"><div><p class="text-[10px] font-black uppercase tracking-wider text-red-700">Funding leg</p><p class="text-sm font-black mt-0.5">Sell existing holding</p></div><span class="text-[9px] font-black uppercase rounded-full bg-red-50 text-red-700 px-2 py-1">SELL</span></div>\n                            <div class="grid grid-cols-2 gap-3"><div><label class="label" for="allocation-funding-symbol">Ticker</label><input id="allocation-funding-symbol" class="field uppercase" value="VUAG.L" required></div><div><label class="label" for="allocation-funding-qty">Quantity</label><input id="allocation-funding-qty" type="number" min="0" step="0.000001" class="field" required></div></div>\n                            <div class="grid grid-cols-2 gap-3"><div><label class="label" for="allocation-funding-price">Price</label><input id="allocation-funding-price" type="number" min="0" step="0.0001" class="field" required></div><div><label class="label" for="allocation-funding-fees">Fees</label><input id="allocation-funding-fees" type="number" min="0" step="0.01" value="0" class="field" required></div></div>\n                        </div>\n                        <div class="rounded-xl border border-gray-200 bg-gray-50 p-4 space-y-3">\n                            <div class="flex items-center justify-between"><div><p class="text-[10px] font-black uppercase tracking-wider text-emerald-700">Target leg</p><p class="text-sm font-black mt-0.5">Buy new investment</p></div><span class="text-[9px] font-black uppercase rounded-full bg-emerald-50 text-emerald-700 px-2 py-1">BUY</span></div>\n                            <div class="grid grid-cols-[.7fr_1.3fr] gap-3"><div><label class="label" for="allocation-target-symbol">Ticker</label><input id="allocation-target-symbol" class="field uppercase" placeholder="e.g. LSEG.L" required></div><div><label class="label" for="allocation-target-name">Instrument name</label><input id="allocation-target-name" class="field" placeholder="Company name" required></div></div>\n                            <div class="grid grid-cols-2 sm:grid-cols-4 gap-3"><div><label class="label" for="allocation-target-currency">Currency</label><select id="allocation-target-currency" class="field"><option>GBP</option><option>USD</option><option>EUR</option></select></div><div><label class="label" for="allocation-target-fx">FX to GBP</label><input id="allocation-target-fx" type="number" min="0" step="0.000001" value="1" class="field"></div><div><label class="label" for="allocation-target-qty">Quantity</label><input id="allocation-target-qty" type="number" min="0" step="0.000001" class="field" required></div><div><label class="label" for="allocation-target-price">Price</label><input id="allocation-target-price" type="number" min="0" step="0.0001" class="field" required></div></div>\n                            <div class="max-w-[180px]"><label class="label" for="allocation-target-fees">Fees</label><input id="allocation-target-fees" type="number" min="0" step="0.01" value="0" class="field" required></div>\n                        </div>\n                    </div>\n                    <div class="grid lg:grid-cols-[1.25fr_.75fr] gap-4 items-end">\n                        <div><label class="label" for="allocation-reason">Decision note</label><textarea id="allocation-reason" rows="3" class="field resize-y" placeholder="Short factual note tying the funding sale and new purchase to the same allocation decision" required></textarea></div>\n                        <div id="allocation-preview" class="rounded-xl bg-blue-50 border border-blue-100 px-4 py-3 text-xs text-blue-900 leading-relaxed">Enter both legs to preview funding versus purchase cost.</div>\n                    </div>\n                    <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3">\n                        <p class="text-[11px] text-gray-400 leading-relaxed">This records the ledger decision only. After success, the new BUY will be pre-selected in the journal form below so the investment thesis can be documented separately.</p>\n                        <button id="allocation-submit" type="submit" class="shrink-0 rounded-xl bg-blue-700 text-white px-5 py-3 text-sm font-black hover:bg-blue-800 transition">Record active allocation</button>\n                    </div>\n                </form>\n            </section>\n\n''' + marker
if marker not in s:
    raise SystemExit('main transaction grid marker missing')
s = s.replace(marker, card, 1)

old = '''            const isCorrection = /^(REVERSAL|CORRECTION) of /.test(txn.note || '');\n'''
new = '''            const isCorrection = /^(REVERSAL|CORRECTION) of /.test(txn.note || '');\n            const isAllocation = /^ALLOCATION [a-f0-9]{12} /.test(txn.note || '');\n'''
if old not in s:
    raise SystemExit('recent transaction classification marker missing')
s = s.replace(old, new, 1)
old = '''            if (isCorrection) { const badge=document.createElement('span'); badge.className='text-[9px] font-black uppercase tracking-wider rounded-full px-2 py-0.5 bg-amber-50 text-amber-700'; badge.textContent=(txn.note||'').startsWith('REVERSAL')?'Reversal':'Corrected'; top.appendChild(badge); }\n'''
new = old + '''            if (isAllocation) { const badge=document.createElement('span'); badge.className='text-[9px] font-black uppercase tracking-wider rounded-full px-2 py-0.5 bg-blue-50 text-blue-700'; badge.textContent='Allocation'; top.appendChild(badge); }\n'''
if old not in s:
    raise SystemExit('recent transaction badge marker missing')
s = s.replace(old, new, 1)

js_marker = '''    function updateTransactionPreview() {\n'''
js = '''    function updateAllocationPreview() {\n        const fundingQty=Number(el('allocation-funding-qty').value||0), fundingPrice=Number(el('allocation-funding-price').value||0), fundingFees=Number(el('allocation-funding-fees').value||0);\n        const targetQty=Number(el('allocation-target-qty').value||0), targetPrice=Number(el('allocation-target-price').value||0), targetFees=Number(el('allocation-target-fees').value||0), targetFx=Number(el('allocation-target-fx').value||1);\n        if(!fundingQty || fundingPrice<0 || !targetQty || targetPrice<0){ el('allocation-preview').textContent='Enter both legs to preview funding versus purchase cost.'; return; }\n        const proceeds=fundingQty*fundingPrice-fundingFees;\n        const targetLocal=targetQty*targetPrice+targetFees;\n        const targetBase=targetLocal*targetFx;\n        const residual=proceeds-targetBase;\n        el('allocation-preview').textContent=`Funding proceeds: ${money(proceeds,'GBP')} · Target cost: ${money(targetBase,'GBP')} · Net cash impact: ${residual>=0?'+':''}${money(residual,'GBP')}.`;\n    }\n    ['allocation-funding-qty','allocation-funding-price','allocation-funding-fees','allocation-target-qty','allocation-target-price','allocation-target-fees','allocation-target-fx'].forEach(id=>el(id).addEventListener('input',updateAllocationPreview));\n    el('allocation-target-currency').addEventListener('change',()=>{ if(el('allocation-target-currency').value==='GBP') el('allocation-target-fx').value='1'; updateAllocationPreview(); });\n\n    el('allocation-form').addEventListener('submit', async event=>{\n        event.preventDefault();\n        const payload={\n            trade_date:el('allocation-date').value,\n            funding_symbol:el('allocation-funding-symbol').value.trim().toUpperCase(),\n            funding_quantity:Number(el('allocation-funding-qty').value),\n            funding_price:Number(el('allocation-funding-price').value),\n            funding_fees:Number(el('allocation-funding-fees').value||0),\n            target_symbol:el('allocation-target-symbol').value.trim().toUpperCase(),\n            target_name:el('allocation-target-name').value.trim(),\n            target_asset_type:'equity',\n            target_currency:el('allocation-target-currency').value,\n            target_quantity:Number(el('allocation-target-qty').value),\n            target_price:Number(el('allocation-target-price').value),\n            target_fees:Number(el('allocation-target-fees').value||0),\n            target_fx_rate_to_base:Number(el('allocation-target-fx').value||1),\n            reason:el('allocation-reason').value.trim()\n        };\n        const warning=`Record one active allocation on ${payload.trade_date}?\\n\\nSELL ${payload.funding_quantity} ${payload.funding_symbol} @ ${payload.funding_price}\\nBUY ${payload.target_quantity} ${payload.target_symbol} @ ${payload.target_price} ${payload.target_currency}\\n\\nBoth ledger rows will be permanent and share one decision ID.`;\n        if(!confirm(warning)) return;\n        const btn=el('allocation-submit'); btn.disabled=true; btn.textContent='Recording allocation…';\n        try{\n            const result=await apiFetch(`/admin/${PORTFOLIO}/active-allocation`,{method:'POST',body:JSON.stringify(payload)});\n            setMessage('global-message',`Active allocation ${result.decision_id} recorded successfully. The new BUY is ready to link to an investment note.`,'success');\n            el('allocation-form').reset(); el('allocation-funding-symbol').value='VUAG.L'; el('allocation-funding-fees').value='0'; el('allocation-target-currency').value='GBP'; el('allocation-target-fx').value='1'; el('allocation-target-fees').value='0'; setTodayDefaults(); updateAllocationPreview();\n            await refreshAdminData();\n            if(result.target_transaction?.id){ el('journal-transaction').value=result.target_transaction.id; el('journal-date').value=payload.trade_date; el('journal-category').value='Investment Note'; el('journal-title').scrollIntoView({behavior:'smooth',block:'center'}); }\n        }catch(error){ setMessage('global-message',error.message,'error'); }\n        finally{ btn.disabled=false; btn.textContent='Record active allocation'; }\n    });\n\n''' + js_marker
if js_marker not in s:
    raise SystemExit('transaction preview marker missing')
s = s.replace(js_marker, js, 1)

old = '''        if (!el('txn-date').value) el('txn-date').value=today;\n        if (!el('journal-date').value) el('journal-date').value=today;\n'''
new = '''        if (!el('txn-date').value) el('txn-date').value=today;\n        if (!el('allocation-date').value) el('allocation-date').value=today;\n        if (!el('journal-date').value) el('journal-date').value=today;\n'''
if old not in s:
    raise SystemExit('date defaults marker missing')
s = s.replace(old,new,1)

p.write_text(s,encoding='utf-8')
print('active allocation admin UI patched')
